L6_1.m_CharStrID = "READ_NPC_MARY_NULL"
L6_1.m_Talk_KOREA = "에이버리와 우리들은 그 재해 속에서 가까스로 살아남은 생존자들이었지."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "エイバリーと私たちは、あの災害からなんとか生き延びた者同士だった。"
L6_1.m_Talk_ENG = "Avery and the rest of us were the barely surviving remnants of that disaster."
