L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "READ_NPC_MARY_NULL"
L7_1.m_Talk_KOREA = "사람들은 살기 위해 서로의 것을 빼앗고, 죽이며 살아남았어."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "人々は生きるために奪い合い、殺し合った。"
L7_1.m_Talk_ENG = "People stole and killed each other just to live."
L7_1.m_Talk_TWN = "人們為了生存互相掠奪、殺戮。"
L7_1.m_Talk_DEU = "People stole and killed each other just to live."
L7_1.m_Talk_FRA = "People stole and killed each other just to live."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@3#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 8000116
L8_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "READ_NPC_MARY_NULL"
L8_1.m_Talk_KOREA = "빼앗기지 않기 위해, 죽지 않기 위해 모여든 사람들은 어느새 하나의 집단이 되었지."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "奪われないために、殺されないために、力を合わせた人々はやがて1つの集団になっていった。"
L8_1.m_Talk_ENG = "To avoid being robbed and to avoid dying, those who gathered together eventually became a single group."
L8_1.m_Talk_TWN = "為了不被掠奪、為了求生，聚集的人們慢慢形成了一個群體。"
L8_1.m_Talk_DEU = "To avoid being robbed and to avoid dying, those who gathered together eventually became a single group."
L8_1.m_Talk_FRA = "To avoid being robbed and to avoid dying, those who gathered together eventually became a single group."
