L21_1.m_Talk_KOREA = "에이버리는 그곳의 풍경을 모두가 보기를 바랐어."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "エイバリーはそこの景色をみんなに見てほしいと願ったわ。"
