L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "READ_NPC_MARY_NULL"
L22_1.m_Talk_KOREA = "이걸 보고 감동한 사람들이 조금이라도 힘을 내지 않을까 생각했거든. "
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "それを見て感動した人々が、少しでも元気を出せるんじゃないかって。 "
L22_1.m_Talk_ENG = "He thought that maybe it would give people the strength to keep going."
L22_1.m_Talk_TWN = "哪怕只是一點點，希望因此被感動的人們能振作起來。 "
