L25_1 = {}
L25_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@12#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 8000116
L25_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "READ_NPC_MARY_NULL"
L25_1.m_Talk_KOREA = "에이버리는 바다를 모험하며 얻은 경험을 바탕으로 침식체를 사냥하고, 아티팩트를 가져와 사람들에게 나눠줬지."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "彼は海を冒険しながら得た経験をもとに、侵食体を狩り、アーティファクトを持ってきて、人々に分け与えたの。"
L25_1.m_Talk_ENG = "Avery hunted the C.O.s on the sea using what he learned from his adventures and shared the Artifacts he brought back."
L25_1.m_Talk_TWN = "艾維利憑藉海上冒險的經驗狩獵侵蝕體、取得神器並分給人們。"
L25_1.m_Talk_DEU = "Avery hunted the C.O.s on the sea using what he learned from his adventures and shared the Artifacts he brought back."
L25_1.m_Talk_FRA = "Avery hunted the C.O.s on the sea using what he learned from his adventures and shared the Artifacts he brought back."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@13#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 8000116
L26_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "READ_NPC_MARY_NULL"
L26_1.m_Talk_KOREA = "사람들을 약탈하던 사람들은 에이버리가 가져온 아티팩트를 보곤 바다로 나가기 시작했어."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "略奪を繰り返していた人々は、彼が持ってきたアーティファクトを見て海に出るようになった。"
L26_1.m_Talk_ENG = "The people who had lived by raiding others saw Avery's Artifacts and began heading out to sea."
L26_1.m_Talk_TWN = "曾經掠奪他人的人看到艾維利帶回的神器，也開始展開海上之路。"
L26_1.m_Talk_DEU = "The people who had lived by raiding others saw Avery's Artifacts and began heading out to sea."
L26_1.m_Talk_FRA = "The people who had lived by raiding others saw Avery's Artifacts and began heading out to sea."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@14#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 8000116
L27_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "READ_NPC_MARY_NULL"
L27_1.m_Talk_KOREA = "그것이 프론트 베이에 해적이 생겨난 이유란다."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "それが、フロントベイに海賊が生まれた理由なのよ。"
L27_1.m_Talk_ENG = "That's why pirates were born in Front Bay."
L27_1.m_Talk_TWN = "這就是為什麼前灣會出現海盜的原因。"
L27_1.m_Talk_DEU = "That's why pirates were born in Front Bay."
