L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 8000116
L31_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_StartFXSoundControl = "NCSC_LOOP_PLAY"
L31_1.m_StartFXSoundName = "FX_CUTSCEN_CROWD_CHILD"
L31_1.m_CharStrID = "READ_NPC_MARY_NULL"
L31_1.m_Talk_KOREA = "그렇게 육지의 사람들은 서서히 질서를 되찾았단다."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "そうやって陸地は徐々に秩序を取り戻していったわ。"
L31_1.m_Talk_ENG = "And slowly, the people on land regained order."
L31_1.m_Talk_TWN = "陸地上的人們逐漸找回秩序。"
L31_1.m_Talk_DEU = "And slowly, the people on land regained order."
L31_1.m_Talk_FRA = "And slowly, the people on land regained order."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@16#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 8000116
L32_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "READ_NPC_MARY_NULL"
L32_1.m_Talk_KOREA = "내일을 꿈꾸길 포기한 사람들은 다시 오늘의 별을 바라보며 잠들 수 있게 되었지."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "明日を夢見ることを諦めていた人々は、再び今日の星を見上げて眠れるようになった。"
L32_1.m_Talk_ENG = "Those who had given up dreaming of tomorrow were once again able to sleep while looking up at the stars."
L32_1.m_Talk_TWN = "放棄夢想明天的人，也能重新仰望今夜的星空入眠。"
L32_1.m_Talk_DEU = "Those who had given up dreaming of tomorrow were once again able to sleep while looking up at the stars."
L32_1.m_Talk_FRA = "Those who had given up dreaming of tomorrow were once again able to sleep while looking up at the stars."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@17#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 8000116
L33_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "READ_NPC_MARY_NULL"
L33_1.m_Talk_KOREA = "하지만 그런 우리도 피할 수 없는 시간이 찾아왔어."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "でも、そんな私たちにも避けられない瞬間がやってきたの。"
L33_1.m_Talk_ENG = "But even we couldn't escape the passage of time."
L33_1.m_Talk_TWN = "然而我們無法逃避的考驗也找上門了。"
L33_1.m_Talk_DEU = "But even we couldn't escape the passage of time."
L33_1.m_Talk_FRA = "But even we couldn't escape the passage of time."
