L38_1 = {}
L38_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@19#Talk"
L38_1.m_CutScenProcessKey = 38
L38_1.m_CutScenID = 8000116
L38_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_bLooseShake = true
L38_1.m_Face = "UNIT_SERIOUS"
L38_1.m_CharStrID = "SECRETARY_FRONTBAY_NULL_ADMIN"
L38_1.m_bCharHologramEffect = true
L38_1.m_Talk_KOREA = "당시 사람들은 바다에서 엄청난 빛기둥이 솟아오른 것은 목격했지만……."
L38_1.m_fTalkTime = 0.03
L38_1.m_Talk_JPN = "当時、人々は海から巨大な光の柱が立つところは目撃したものの……"
L38_1.m_Talk_ENG = "Witnesses saw a massive pillar of light shoot up from the sea..."
L38_1.m_Talk_TWN = "當時人們看到巨大的光柱自海面升起……"
L38_1.m_Talk_DEU = "Witnesses saw a massive pillar of light shoot up from the sea..."
L38_1.m_Talk_FRA = "Witnesses saw a massive pillar of light shoot up from the sea..."
L39_1 = {}
L39_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@20#Talk"
L39_1.m_CutScenProcessKey = 39
L39_1.m_CutScenID = 8000116
L39_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_bLooseShake = true
L39_1.m_Face = "UNIT_SERIOUS"
L39_1.m_CharStrID = "SECRETARY_FRONTBAY_NULL_ADMIN"
L39_1.m_bCharHologramEffect = true
L39_1.m_Talk_KOREA = "그 빛기둥 속에서 무엇이 기어 나왔는지는 확인하지 못했으니까요."
L39_1.m_fTalkTime = 0.03
L39_1.m_Talk_JPN = "その光の柱から何が出てきたかは確認できませんでした。"
L39_1.m_Talk_ENG = "But no one saw what crawled out of that pillar of light."
L39_1.m_Talk_TWN = "卻無法確認從光柱爬出的東西是什麼。"
L39_1.m_Talk_DEU = "But no one saw what crawled out of that pillar of light."
L39_1.m_Talk_FRA = "But no one saw what crawled out of that pillar of light."
