L43_1.m_CharStrID = "SECRETARY_FRONTBAY_NULL_ADMIN"
L43_1.m_Talk_KOREA = "무한 증식형 4종 침식체, 식별명 크라켄은 대균열 속에서 유체 형태로 바다에 부상했습니다."
L43_1.m_fTalkTime = 0.03
L43_1.m_Talk_JPN = "無限増殖型第4種侵食体、識別名クラーケンは大亀裂の中から幼体の形で海に浮上しました。"
L43_1.m_Talk_ENG = "The endlessly multiplying Category 4 C.O., designated Kraken, surfaced from the Grand Dimension Crevice in a larva form."
L43_1.m_Talk_TWN = "無限增殖型4類侵蝕體，識別名「克拉肯」。以流體形態自大峽谷浮出海面。"
L43_1.m_Talk_DEU = "The endlessly multiplying Category 4 C.O., designated Kraken, surfaced from the Grand Dimension Crevice in a larva form."
L43_1.m_Talk_FRA = "The endlessly multiplying Category 4 C.O., designated Kraken, surfaced from the Grand Dimension Crevice in a larva form."
L44_1 = {}
L44_1.m_CutScenKey_Talk = "OMEN_FRONTBAY_INTERUDE9@22#Talk"
