L44_1.m_bLooseShake = true
L44_1.m_CharStrID = "SECRETARY_FRONTBAY_NULL_ADMIN"
L44_1.m_Talk_KOREA = "바다의 모든 것을 닥치는 대로 집어삼킨 녀석은… 어느새 재해를 일으킬 정도로 거대해졌죠."
L44_1.m_fTalkTime = 0.03
L44_1.m_Talk_JPN = "海のすべてを手当たり次第貪り尽くしたそれは……やがて災害を引き起こすほど巨大になっていきました。"
L44_1.m_Talk_ENG = "It devoured everything in the ocean... and grew into a disaster-class monster."
L44_1.m_Talk_TWN = "吞噬大海一切的它……很快變大到足以引發災難的規模。"
L44_1.m_Talk_DEU = "It devoured everything in the ocean... and grew into a disaster-class monster."
L44_1.m_Talk_FRA = "It devoured everything in the ocean... and grew into a disaster-class monster."
