L1_1.m_CharStrID = "READ_NPC_MARY_NULL"
L1_1.m_Talk_KOREA = "그 당시엔 그렇게 생각했지만, 지금은 로스트 쉽이라 부르는 함선……."
L1_1.m_fTalkTime = 0.03
L1_1.m_Talk_JPN = "当時はそう思ってたけど……今はロストシップと呼ばれている艦船……"
L1_1.m_Talk_ENG = "That's what we thought back then, but now we call it the Lost Ship–"
