L11_1.m_CharStrID = "READ_NPC_MARY_NULL"
L12_1 = "크라켄이 그 소리에 자극받은 건지는 모르겠다만, 우리에게 인빈서블을 집어 던졌고……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "その音に刺激されたのか、クラーケンは私たちにインビンシブルを投げつけ……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Maybe Kraken reacted to that shouting because it threw the Invincible at us..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "不知道克拉肯是否因此受到刺激，它把無敵號扔向我們……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "Maybe Kraken reacted to that shouting because it threw the Invincible at us..."
L11_1.m_Talk_DEU = L12_1
