L12_1.m_CharStrID = "READ_NPC_MARY_NULL"
L13_1 = "그게 우리에게 있어서 절호의 기회가 되었지."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "それが私たちにとっての絶好のチャンスになったわ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "And that became our chance."
L12_1.m_Talk_ENG = L13_1
L13_1 = "那對我們來說是千載難逢的機會。"
