L18_1.m_CharStrID = "READ_NPC_MARY_NULL"
L19_1 = "에이버리는 <color=#ffd34c>해적은 모험의 연속</color>이라고 말하며 겁도 없이 함선 안으로 들어갔단다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "エイバリーは<color=#ffd34c>海賊は冒険の連続</color>だと言って、なんと大胆にも艦船の中に入っていったの。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Avery said, <color=#ffd34c>\"A pirate's life is endless adventure,\"</color> and strode right into the ship without hesitation."
L18_1.m_Talk_ENG = L19_1
L19_1 = "艾維利說<color=#ffd34c>海盜就是冒險的延續</color>，毫無畏懼衝進艦船。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "Avery said, <color=#ffd34c>\"A pirate's life is endless adventure,\"</color> and strode right into the ship without hesitation."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Avery said, <color=#ffd34c>\"A pirate's life is endless adventure,\"</color> and strode right into the ship without hesitation."
L18_1.m_Talk_FRA = L19_1
