L19_1.m_CharStrID = "READ_NPC_MARY_NULL"
L20_1 = "함선 내부는 외계인이 실험 시설이 펼쳐져 있을 거란 우리의 기대와는 달리 처참했지."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "艦船の内部は、宇宙人の実験施設があるだろうという私たちの期待とは全く違って、凄惨な状況だった。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But inside the ship, instead of some alien test facility we expected, was pure carnage."
L19_1.m_Talk_ENG = L20_1
L20_1 = "艦船內完全跟我們預想的外星實驗設施不同，而是慘不忍睹。"
