L25_1.m_CharStrID = "READ_NPC_MARY_NULL"
L26_1 = "알아들을 수 없는 말을 하며 공격하는 기계 병기들."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "理解できない言葉を発しながら攻撃してくる機械兵器の数々。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Machines speaking nonsense as they attacked us."
L25_1.m_Talk_ENG = L26_1
L26_1 = "口中說著聽不懂的語言並攻擊的機械兵器。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "Machines speaking nonsense as they attacked us."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Machines speaking nonsense as they attacked us."
L25_1.m_Talk_FRA = L26_1
