L27_1 = "OMEN_FRONTBAY_INTERUDE9@34#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 8000116
L26_1.m_CutScenStrID = "OMEN_FRONTBAY_INTERUDE9"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "READ_NPC_MARY_NULL"
L27_1 = "에이버리가 앞장서지 않았다면 우리도 검은 범람이고 뭐고 겁에 질려 도망치기 바빴을 거란다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "エイバリーが先頭に立ってくれていなかったら、私たちも黒い氾濫はそっちのけで恐怖のあまり逃げ出していたでしょうね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "If Avery hadn't led the way, we would've run in terror before dealing with the Black Flood or anything else."
L26_1.m_Talk_ENG = L27_1
L27_1 = "如果艾維利不帶頭，我們可能早就被黑色洪災嚇到逃跑了。"
L26_1.m_Talk_TWN = L27_1
