L22_1 = "모네카. 우리는 지금 우리 고향을 덮친 검은 범람을 끝내기 위해 위험을 무릅쓰고 여기 왔어."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "モネカ。私たちは今、故郷を襲った黒い氾濫を終わらせるために危険を冒してまでここに来てる。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Moneka. We came risking our lives to end the Black Flood ravaging our home."
L21_1.m_Talk_ENG = L22_1
L22_1 = "莫奈卡。我們冒著危險來到這裡，就是為了終結侵襲我們故鄉的黑色洪災。"
