L23_1 = "너와 네 선원들에게는 못 할 말이지만, 검은 범람을… 크라켄을 이길 수 있는 방법이 필요해."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "あんたとあんたの船員には悪いが、黒い氾濫に……クラーケンに勝てる方法が必要なんだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "This isn't something your crew would want to hear, but we need a way to defeat the Black Flood... to defeat Kraken."
L22_1.m_Talk_ENG = L23_1
L23_1 = "或許不能對你和你的船員這麼說……但我們需要能戰勝黑色洪災、戰勝克拉肯的方法。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "This isn't something your crew would want to hear, but we need a way to defeat the Black Flood... to defeat Kraken."
