L38_1 = "인빈서블과 함께 에이버리 해적단은 크라켄과 맞서 싸웠고, 크라켄과 함께 바닷속으로 사라졌다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "インビンシブルと共にエイバリー海賊団はクラーケンに立ち向かい、クラーケンと共に海の底へ消えた。"
